def test_read_settings():
    text = 'name = disc one\n\n# a comment\n  # an indented comment\nkind=film\n'
    assert read_settings(text) == {'name': 'disc one', 'kind': 'film'}
    assert read_settings('') == {}
    assert read_settings('\n\n') == {}


def test_read_settings_depends_on_its_lines():
    assert read_settings('a = 1') != read_settings('a = 2')


def test_read_settings_keeps_every_key():
    assert len(read_settings('a = 1\nb = 2\nc = 3')) == 3


def test_read_settings_refuses_a_key_given_twice():
    with pytest.raises(ValueError):
        read_settings('a = 1\na = 2')


def test_read_settings_refuses_a_line_that_is_not_a_pair():
    with pytest.raises(ValueError):
        read_settings('a = 1\nnot a pair')

def test_read_pair():
    assert read_pair('name = disc one') == ('name', 'disc one')
    assert read_pair('a=b') == ('a', 'b')
    assert read_pair('url = http://x?y=1') == ('url', 'http://x?y=1')
    assert read_pair('empty =') == ('empty', '')


def test_read_pair_depends_on_the_line():
    assert read_pair('a = 1') != read_pair('b = 1')
    assert read_pair('a = 1') != read_pair('a = 2')


def test_read_pair_strips_only_the_ends():
    assert read_pair('  key  =  two words  ') == ('key', 'two words')


def test_read_pair_refuses_what_is_not_a_pair():
    for bad in ('no equals sign', '= value', '   = value', ''):
        with pytest.raises(ValueError):
            read_pair(bad)

